SELECT * FROM (
    SELECT ROWNUM AS RN, T.* FROM (
        SELECT


        WHERE P.IS_DELETED = 0
          AND P.IS_BLIND   = 0

            AND P.BOARD_ID = #{boardId}


            AND (P.TITLE LIKE '%' || #{keyword} || '%'
            OR  P.CONTENT LIKE '%' || #{keyword} || '%')

        ORDER BY P.CREATED_AT DESC
    ) T
    WHERE ROWNUM  <=  #{page} * #{size}
)
WHERE RN > (#{page} - 1) * #{size}

